"""Write src/pbremaster/data/iamonds.py from the shape table at 0x5b440c in PANDORA.EUL.

Entry (type * 6 + rotation) * 2 + flip points at: u8 width, u8 height,
u8 first-triangle-points-down, then width*height bytes (non-zero = filled).
"""
import sys

sys.path.insert(0, __file__.rsplit("/", 1)[0])
from pe import Image  # noqa: E402

img = Image(sys.argv[1] if len(sys.argv) > 1 else "../Pandoras_Box_Original/DATA/PANDORA.EUL")
lines = ['"""Interlock piece shapes: SHAPES[type][rotation][flip] = (width, height, down, rows).',
         "",
         "Generated by tools/re/dump_iamonds.py from the table at 0x5b440c in PANDORA.EUL.",
         "Rows use '#' for a filled triangle. `down` says whether the triangle at (0, 0)",
         'points down; neighbours alternate along rows and columns."""',
         "", "SHAPES = ["]
for t in range(7):
    lines.append("    [")
    for r in range(6):
        pair = []
        for f in range(2):
            p = img.u32(0x5b440c + 4 * ((t * 6 + r) * 2 + f))
            m = img.mem[p - img.base:p - img.base + 64]
            w, h, down = m[0], m[1], m[2]
            rows = ["".join("#" if m[3 + y * w + x] else "." for x in range(w)) for y in range(h)]
            pair.append(f"({w}, {h}, {bool(down)}, {tuple(rows)!r})")
        lines.append(f"        [{pair[0]}, {pair[1]}],")
    lines.append("    ],")
lines.append("]")
open("src/pbremaster/data/iamonds.py", "w").write("\n".join(lines) + "\n")
